(function () {
  var photos = window.GALLERY_PHOTOS || [];
  var newPhotoCount = 12;
  var legacyCount = photos.length - newPhotoCount;
  if (legacyCount < 1) return;

  var reordered = [];
  for (var index = 0; index < legacyCount; index++) {
    reordered.push(photos[index]);
    if (index < newPhotoCount) {
      reordered.push(photos[legacyCount + index]);
    }
  }
  window.GALLERY_PHOTOS = reordered;
})();
